    /*
     * Timetable Management delegation (staff_profiles.can_manage_timetable
     * — see EnsureCanManageTimetable's doc comment): a delegated staff
     * member reaches admin.timetable.* routes even though their own
     * role's branch above doesn't grant them, so nav needs a matching
     * link or the module would be reachable only by typing the URL.
     * Only 'teacher' has a real dashboard among the roles this can be
     * granted to today (SessionController::dashboardPathFor() has no
     * branch yet for accountant/librarian/receptionist/staff), hence
     * checking $roleKey !== 'school_admin' generally rather than listing
     * every delegatable role by name — a school_admin already has this
     * link from their own branch above, so this exists purely to avoid
     * a second, differently-labelled entry for them.
     */
    if ($roleKey !== 'school_admin' && $actor?->staffProfile?->can_manage_timetable) {
        $items[] = [
            'admin.timetable.index',
            'Timetable (Admin)',
            'M6.75 3v2.25M17.25 3v2.25M3 18.75V7.5a2.25 2.25 0 0 1 2.25-2.25h13.5A2.25 2.25 0 0 1 21 7.5v11.25m-18 0A2.25 2.25 0 0 0 5.25 21h13.5A2.25 2.25 0 0 0 21 18.75m-18 0v-7.5A2.25 2.25 0 0 1 5.25 9h13.5A2.25 2.25 0 0 1 21 11.25v7.5',
            ['admin.timetable.*'],
            '0 0 24 24',
            '1.5',
        ];
    }
@endphp

@foreach ($items as [$routeName, $label, $iconPath, $activePatterns, $iconViewBox, $iconStrokeWidth])
    <a
        href="{{ route($routeName) }}"
        class="flex items-center gap-3 rounded-md px-3 py-2 text-sm font-medium
            {{ request()->routeIs(...$activePatterns)
                ? 'bg-indigo-50 text-indigo-700'
                : 'text-gray-600 hover:bg-gray-50 hover:text-gray-900' }}"
        @if (request()->routeIs(...$activePatterns)) aria-current="page" @endif
    >
        <svg class="h-5 w-5 shrink-0" viewBox="{{ $iconViewBox }}" fill="none" stroke="currentColor" stroke-width="{{ $iconStrokeWidth }}" stroke-linecap="round" stroke-linejoin="round">
            <path d="{{ $iconPath }}"/>
        </svg>
        {{ $label }}
    </a>
@endforeach
